  // gh-1934 rework-3: the legacy gate (a `security default-keychain`
  // probe) cannot see a locked/unusable login keychain — on self-hosted
  // runner fa-m5-3 it exits 0 while the actual `add-generic-password`
  // write fails (exit -1), reddening the macOS cube-kernel-live leg. Gate
  // the leg FUNCTIONALLY instead: rehearse the exact write→read→delete
  // contract on a throwaway probe item (the same shape as the accepted
  // `hostHasFunctionalKillall` gate from the round-2 fix).
  Future<bool> functionalGate() async {
    if (!Platform.isMacOS) return false;
    // Bounded runner (secureKeyProcessTimeout): a helper stuck on a system
    // modal reports the timeout verdict (exit -1) and the leg skips — the
    // probe can never hang CI. On a healthy macOS host the probe performs
    // one real write→read→delete of the throwaway FA_KEY_SELFTEST_PROBE
    // item at file load (deleted immediately, distinct from the leg's own
    // FA_KEY_SELFTEST_GH1059 item).
    try {
      return await functionalKeychainRoundTrip(
        (args) => secureKeyProcessRunner('security', args),
        service: secureKeyServiceName,
        account: keychainProbeAccount,
        password: [REDACTED:Sensitive Value],
      );
    } on Object {
      return false;
    }
  }

  final bool hostHasFunctionalKeychainWrite = await functionalGate();

  // gh-1934 rework-3: the keychain leg's skip gate is a FUNCTIONAL
  // round-trip probe, decided by the same pure logic these side-effect-free
  // tests pin (fake `security` runners — nothing here touches a real
  // keychain). The CI red this gate replaces: runner fa-m5-3 passed the
  // old `security default-keychain` preflight, then the actual
  // `add-generic-password` write failed (exit -1) on its locked login
  // keychain — the leg must SKIP that shape, not fail.
  group('functional keychain round-trip probe (gh-1934 rework-3)', () {
    // Scripted `security` CLI: answers per first argument, records calls.
    ({
      Future<SecureKeyRunResult> Function(List<String> args) run,
      List<String> calls,
    })
    script({
      int defaultKeychain = 0,
      int add = 0,
      int find = 0,
      String findPassword = keychainProbePassword,
      int delete = 0,
    }) {
      final calls = <String>[];
      Future<SecureKeyRunResult> run(List<String> args) async {
        calls.add(args.first);
        return switch (args.first) {
          'default-keychain' => SecureKeyRunResult(defaultKeychain, ''),
          'add-generic-password' => SecureKeyRunResult(add, ''),
          'find-generic-password' => SecureKeyRunResult(
            find,
            '$findPassword\n',
          ),
          'delete-generic-password' => SecureKeyRunResult(delete, ''),
          _ => SecureKeyRunResult(64, ''),
        };
      }

      return (run: run, calls: calls);
    }

    Future<bool> probeOf(Object scripted) async {
      final s =
          scripted
              as ({
                Future<SecureKeyRunResult> Function(List<String> args) run,
                List<String> calls,
              });
      return functionalKeychainRoundTrip(
        s.run,
        service: secureKeyServiceName,
        account: keychainProbeAccount,
        password: [REDACTED:Sensitive Value],
      );
    }

    test('a real write→read→delete round-trip makes the leg usable', () async {
      final s = script();
      expect(await probeOf(s), isTrue);
      expect(s.calls, [
        'default-keychain',
        'add-generic-password',
        'find-generic-password',
        'delete-generic-password',
      ]);
    });

    test(
      'a locked keychain — preflight ok, the WRITE fails — skips the leg',
      () async {
        // The fa-m5-3 CI shape: default-keychain exits 0, the real
        // add-generic-password write fails (exit -1).
        expect(await probeOf(script(add: -1)), isFalse);
      },
    );

    test('a missing default keychain skips the leg and never writes', () async {
      final s = script(defaultKeychain: 36);
      expect(await probeOf(s), isFalse);
      expect(s.calls, ['default-keychain']);
    });

    test(
      'a read-back that returns a different secret skips the leg and still deletes the probe item',
      () async {
        final s = script(findPassword: 'a-different-secret');
        expect(await probeOf(s), isFalse);
        expect(s.calls.last, 'delete-generic-password');
      },
    );

    test(
      'a failed delete skips the leg — the probe item must not survive',
      () async {
        expect(await probeOf(script(delete: 1)), isFalse);
      },
    );

    test('a helper hung on a system modal — the bounded timeout verdict '
        '(exit -1, timedOut) — skips the leg instead of wedging it', () async {
      // secureKeyProcessTimeout kills a helper stuck on the macOS
      // "Keychain Not Found" modal and reports exitCode -1 + timedOut —
      // the CI red's exact `exit -1` signature. The probe must read that
      // as "cannot run" (skip), never as a hang or a retryable failure.
      Future<SecureKeyRunResult> run(List<String> args) async =>
          switch (args.first) {
            'default-keychain' => const SecureKeyRunResult(0, ''),
            'add-generic-password' => const SecureKeyRunResult(
              -1,
              '',
              timedOut: true,
            ),
            _ => const SecureKeyRunResult(64, ''),
          };
      expect(
        await functionalKeychainRoundTrip(
          run,
          service: secureKeyServiceName,
          account: keychainProbeAccount,
          password: [REDACTED:Sensitive Value],
        ),
        isFalse,
      );
    });
  });

  // `tags: integration` (gh-1059 review): this group performs a REAL
  // `security add-generic-password` against the developer's default
  // keychain — excluded from the pre-commit gate and the plain per-PR
  // core shards, executed by ci.yml's macOS cube-kernel-live leg
  // (`dart test test/secrets/secure_key_store_test.dart --tags
  // integration`) and runnable standalone with `--tags integration`.
  // (The file-level `@Tags` form would sweep the side-effect-free
  // `sleep`/`sh` runner groups into the tag; the group parameter keeps
  // them untagged.)
  group('real keychain runner (gh-1059 AC4, macOS only)', () {
    const testName = 'FA_KEY_SELFTEST_GH1059';

    test(
      'the bounded runner writes, reads and deletes a real keychain item',
      // CI guard, not an assumption: the functional probe above decides —
      // and the skip reason names the remedy for a host that wants the
      // coverage back (unlock/fix the runner keychain).
      skip: Platform.isMacOS && hostHasFunctionalKeychainWrite
          ? false
          : 'macOS keychain only: needs a `security` CLI whose default '
                'keychain completes a real generic-password write→read→delete '
                'round-trip (gh-1934 rework-3: headless runner keychains can '
                'pass the default-keychain preflight yet fail the write — '
                'unlock/fix the keychain to run this leg)',
      () async {
        final store = platformSecureKeyStore();

        await store.write(testName, 'sk-gh1059-selftest');
        try {
          final read = await store.read(testName);
          expect(read, 'sk-gh1059-selftest');
        } finally {
          await store.delete(testName);
        }
        expect(await store.read(testName), isNull);
      },
      timeout: const Timeout(Duration(seconds: 60)),
    );
  }, tags: 'integration');
}

/// Platform secure storage for API keys (OS keychains) with a synchronous
/// session cache.
///
/// [SecureKeyStore] abstracts the host's secure enclave — macOS Keychain,
/// freedesktop Secret Service (gnome-keyring/KWallet via `secret-tool`), or
/// the Windows Credential Locker. The platform implementations live in
/// `secure_key_store_io.dart` (`dart:io`, exported only from `lib/io.dart`);
/// this file stays pure Dart so the CLI core compiles for web.
///
/// Keychain reads spawn helper processes and are therefore async, while the
/// CLI's key lookups (`AgentCliConfig.envVarValue`/`envVarIsSet`, the roles
/// secrets snapshot) are synchronous — [SecureKeyCache] bridges that gap:
/// the host preloads the names it cares about once at startup and all later
/// reads hit the in-memory snapshot. Writes go through to the store and
/// update the snapshot atomically.
library;

/// A platform secure enclave for secrets, addressed by name.
abstract interface class SecureKeyStore {
  /// A short human label for messages (e.g. `macOS Keychain`).
  String get label;

  /// Whether the backend is usable on this host (helper binary present, a
  /// Secret Service provider on the session bus, ...). False means the host
  /// falls back to environment-only keys — never an error.
  Future<bool> isAvailable();

  /// Returns the stored value for [name], or null when absent.
  Future<String?> read(String name);

  /// Stores [value] under [name], replacing any existing entry.
  Future<void> write(String name, String value);

  /// Removes [name] (no-op when absent).
  Future<void> delete(String name);
}

/// The classified outcome of one secure-store read (gh-1059 observability).
enum SecureKeyReadStatus { found, absent, error }

/// One preload read's classified result: [status] with the resolved
/// [value] (`found` only) or a one-line [error] diagnostic (`error` only).
///
/// The diagnostic carries the exit code / stderr tail / timeout note —
/// never the secret itself (reads print secrets to stdout, errors to
/// stderr).
final class SecureKeyReadOutcome {
  /// Creates an outcome; [value] and [error] are mutually exclusive.
  const SecureKeyReadOutcome(this.name, this.status, {this.value, this.error});

  /// The store name that was read.
  final String name;

  /// The classification.
  final SecureKeyReadStatus status;

  /// The resolved secret (`found` only; empty values read as `absent`).
  final String? value;

  /// A one-line backend diagnostic — exit code, stderr tail, timeout or
  /// validation note. Never contains the secret.
  final String? error;
}

/// Collapses a diagnostic to one log-safe line: trim → collapse internal
/// whitespace → keep the LAST 200 chars (failures announce themselves in
/// the tail). The ONE canonical collapse (gh-1059 review): both the
/// preload error paths and the platform runner's captured stderr go
/// through it, so boot diagnostics and helper diagnostics can never drift
/// apart (a diverged cap would truncate the two surfaces differently).
String secureKeyDiagnosticLine(String text) {
  final flat = text.trim().replaceAll(RegExp(r'\s+'), ' ');
  return flat.length > 200 ? flat.substring(flat.length - 200) : flat;
}

/// Whether [diagnostic] is one of the macOS "no default keychain" write
/// failures (gh-1679): the platform store's write preflight throws the
/// first shape when `security default-keychain` does not resolve, and the
/// actual `add-generic-password` surfaces the second — `The authorization
/// was canceled by the user` (exit 154, the user canceling the system
/// "reset to default" dialog; the incident RCA's live evidence #2). Both
/// share the same root cause (no default keychain pointer) and the same
/// remedy, so both get the advisory + `[y/N]` repair offer. Reads still
/// succeed via the search list on such a host, so only writes fail — the
/// state worth a dedicated remedy.
bool isMissingDefaultKeychainError(String diagnostic) =>
    diagnostic.contains('no default keychain') ||
    diagnostic.contains('authorization was canceled');

/// The advisory remedy line for a missing macOS default keychain
/// (gh-1679 AC6): names the system remedy WITHOUT executing anything —
/// fa reports and advises, never modifies system keychain settings on
/// its own initiative.
String missingDefaultKeychainAdvisory() =>
    'note: macOS has no default keychain, so secure-store writes cannot '
    'land — restore it with: security default-keychain -s '
    '~/Library/Keychains/login.keychain-db (or Keychain Access → Settings '
    '→ "Set as default"), then retry the save';

/// The summary of one [SecureKeyCache.preload] run. The executable turns
/// it into per-name debug lines and the zero-resolved boot warning — the
/// cache itself never prints (a keychain must never break startup, and
/// the pure core has no `dart:io`).
final class SecureKeyPreloadReport {
  /// Creates a report; [outcomes] is empty when the store was unavailable.
  const SecureKeyPreloadReport({
    required this.storeAvailable,
    required this.outcomes,
  });

  /// Whether the backend answered the availability probe. False means no
  /// read was attempted and [outcomes] is empty.
  final bool storeAvailable;

  /// One outcome per requested name (request order, deduped).
  final List<SecureKeyReadOutcome> outcomes;

  /// How many names resolved a value.
  int get foundCount =>
      outcomes.where((o) => o.status == SecureKeyReadStatus.found).length;

  /// How many names the store answered with a clean "not stored".
  int get absentCount =>
      outcomes.where((o) => o.status == SecureKeyReadStatus.absent).length;

  /// How many reads failed for a diagnosable reason (spawn failure, helper
  /// timeout, non-zero exit other than "item not found", invalid name).
  int get errorCount =>
      outcomes.where((o) => o.status == SecureKeyReadStatus.error).length;
}

/// Implemented by backends that can CLASSIFY a read miss (gh-1059): a
/// clean "not stored" vs a failure with a diagnostic. Optional capability —
/// [SecureKeyCache.preload] uses it when the store offers it and falls back
/// to plain [SecureKeyStore.read] otherwise.
abstract interface class SecureKeyDiagnostics {
  /// One classified read: `found` (with [SecureKeyReadOutcome.value]),
  /// `absent`, or `error` (with a one-line [SecureKeyReadOutcome.error]
  /// diagnostic — exit code / stderr tail / timeout — never the secret).
  /// Invalid names throw like [SecureKeyStore.read].
  Future<SecureKeyReadOutcome> readDetailed(String name);
}

/// A synchronous, session-scoped snapshot over a [SecureKeyStore].
///
/// `null` stores (web hosts, tests) are supported: [available] is then false
/// and every read misses, so callers need no null checks beyond [available].
final class SecureKeyCache {
  /// Creates a cache over [store] (may be null → always unavailable).
  SecureKeyCache(this._store);

  final SecureKeyStore? _store;
  final Map<String, String> _snapshot = {};
  final Map<String, String> _failedSaveNames = {};
  var _available = false;
  var _saveFailures = 0;
  String? _lastSaveError;

  /// The backing store's label (for messages), or null when there is none.
  String? get label => _store?.label;

  /// Whether the platform store answered the availability probe (run by
  /// [preload] or [probe]).
  bool get available => _available;

  /// Probes availability without loading anything. Idempotent.
  Future<bool> probe() async {
    final store = _store;
    if (store == null) return false;
    try {
      _available = await store.isAvailable();
    } on Object {
      _available = false;
    }
    return _available;
  }

  /// Probes the store and, when available, loads [names] into the snapshot
  /// (parallel reads; individual misses/errors simply stay absent — a
  /// keychain must never break startup).
  ///
  /// Returns a [SecureKeyPreloadReport] classifying every requested name
  /// (`found` / `absent` / `error` + diagnostic) so the host can surface a
  /// boot where the config references store keys but none resolved, instead
  /// of the silent absence gh-1059 shipped with. Stores offering
  /// [SecureKeyDiagnostics] get the classification from the backend;
  /// plain stores (and thrown errors) degrade to absent / error outcomes.
  Future<SecureKeyPreloadReport> preload(Iterable<String> names) async {
    final requested = names.toSet().toList();
    if (!await probe()) {
      return SecureKeyPreloadReport(storeAvailable: false, outcomes: const []);
    }
    final store = _store!;
    final SecureKeyDiagnostics? diagnostics = store is SecureKeyDiagnostics
        ? store as SecureKeyDiagnostics
        : null;
    final outcomes = await Future.wait(
      requested.map((name) async {
        try {
          if (diagnostics != null) return await diagnostics.readDetailed(name);
          return await _plainOutcome(store, name);
        } on Object catch (error) {
          // A single unreadable entry must not fail the whole preload.
          return SecureKeyReadOutcome(
            name,
            SecureKeyReadStatus.error,
            error: secureKeyDiagnosticLine(error.toString()),
          );
        }
      }),
    );
    for (final outcome in outcomes) {
      final value = outcome.value;
      if (outcome.status == SecureKeyReadStatus.found &&
          value != null &&
          value.isNotEmpty) {
        _snapshot[outcome.name] = value;
      }
    }
    return SecureKeyPreloadReport(storeAvailable: true, outcomes: outcomes);
  }

  /// Synchronous read from the snapshot (null when absent).
  String? read(String name) => _snapshot[name];

  /// The names currently held in the snapshot.
  Iterable<String> get names => _snapshot.keys;

  /// How many save attempts degraded to session-only since process start
  /// (unavailable store or a failing write — gh-1059: the loud per-save
  /// print stays, and `/key` status names the degradations; saves happen
  /// after boot, so the boot summary deliberately does not cover them).
  int get saveFailures => _saveFailures;

  /// The last save degradation's diagnostic, when any.
  String? get lastSaveError => _lastSaveError;

  /// The names whose most recent save degraded to session-only, sorted
  /// (gh-1679): the boot note and the store-health hint key on NAMES,
  /// not just the aggregate count. A successful [save] of a name clears
  /// it from this set.
  List<String> get failedSaveNames => _failedSaveNames.keys.toList()..sort();

  /// The last degradation diagnostic for [name], or null when [name]'s
  /// most recent save succeeded (or never ran). Never contains a secret —
  /// diagnostics are exit codes / stderr tails only.
  String? saveFailureDiagnostic(String name) => _failedSaveNames[name];

  /// Writes [value] through to the store and updates the snapshot. Returns
  /// false when the store is unavailable OR the write fails (locked or
  /// MDM-managed keychain, missing Secret Service provider) — a failing
  /// backend must degrade to session-only, never crash the CLI.
  Future<bool> save(String name, String value) async {
    if (!available) {
      _recordSaveFailure(name, 'secure store unavailable');
      return false;
    }
    try {
      await _store!.write(name, value);
    } on Object catch (error) {
      _recordSaveFailure(name, secureKeyDiagnosticLine(error.toString()));
      return false;
    }
    _snapshot[name] = value;
    _failedSaveNames.remove(name);
    return true;
  }

  /// Deletes [name] from the store and the snapshot. Returns false when the
  /// store is unavailable or the delete fails; deleting an absent name is a
  /// no-op.
  Future<bool> delete(String name) async {
    if (!available) return false;
    try {
      await _store!.delete(name);
    } on Object {
      return false;
    }
    _snapshot.remove(name);
    return true;
  }

  /// Records a degraded save for the `/key` status summary (the per-save
  /// print at the call site stays). [name] joins the degraded set so the
  /// boot note / the store-health hint can name the slot; a later
  /// successful save of the same name clears it.
  void _recordSaveFailure(String name, String message) {
    _saveFailures++;
    _lastSaveError = message;
    _failedSaveNames[name] = message;
  }

  /// Classifies one read off a plain [SecureKeyStore] (no diagnostics
  /// capability): a non-empty value is `found`, everything else `absent`.
  Future<SecureKeyReadOutcome> _plainOutcome(
    SecureKeyStore store,
    String name,
  ) async {
    final value = await store.read(name);
    return value != null && value.isNotEmpty
        ? SecureKeyReadOutcome(name, SecureKeyReadStatus.found, value: value)
        : SecureKeyReadOutcome(name, SecureKeyReadStatus.absent);
  }
}

